<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Carbon\CarbonImmutable;
final class SchoolCashFlow {
 public function __construct(public FinanceAccess $fin){}
 private function day(string $s):string{return CarbonImmutable::parse($s,'UTC')->setTimezone('Asia/Karachi')->toDateString();}
 public function rows(Request $r,array $campuses,string $from,string $to):array{[$sid]=$this->fin->context($r);$rows=[];$add=function(string $type,int $id,int $campus,?int $bank,string $method,string $date,int $delta,bool $correction,string $description,?string $reference=null)use(&$rows,$from,$to){if($date<$from||$date>$to)return;$rows[]=['key'=>$type.':'.$id,'source'=>$type,'source_id'=>$id,'campus_id'=>$campus,'bank_account_id'=>$bank,'account_key'=>$bank?'bank:'.$bank:'cash','method'=>$method,'date'=>$date,'delta'=>$this->fin->money($delta),'correction'=>$correction,'description'=>$description,'reference'=>$reference];};
  $before=CarbonImmutable::parse($to,'Asia/Karachi')->endOfDay()->utc();
  foreach(DB::table('payments')->where('school_id',$sid)->whereIn('campus_id',$campuses)->where('paid_at','<=',$before)->orderBy('id')->get() as $p){if($p->method!=='cash'&&!$p->bank_account_id)$this->fin->fail('A non-cash fee payment has no account. Reconcile legacy entries first.');$add('fee_payment',$p->id,$p->campus_id,$p->bank_account_id,$p->method,$this->day($p->paid_at),SchoolFees::cents($p->amount),false,'Fee receipt '.$p->receipt_no,$p->reference);}
  foreach(DB::table('payment_reversals as v')->join('payments as p','p.id','=','v.payment_id')->where('v.school_id',$sid)->whereIn('p.campus_id',$campuses)->where('v.status','approved')->where('v.reversed_at','<=',$before)->orderBy('v.id')->get(['v.*','p.campus_id','p.bank_account_id as original_bank','p.method as original_method','p.receipt_no']) as $v){if(!in_array($v->kind,['refund','correction'],true)||!$v->reversed_at)$this->fin->fail('An approved legacy fee reversal needs a correction/refund classification.');$correction=$v->kind==='correction';$method=$correction?$v->original_method:$v->refund_method;$bank=$correction?$v->original_bank:$v->refund_bank_account_id;if(!$method||$method!=='cash'&&!$bank)$this->fin->fail('An approved fee refund has an incomplete payment account.');$add('fee_'.$v->kind,$v->id,$v->campus_id,$bank,$method,$this->day($v->reversed_at),-SchoolFees::cents($v->amount),$correction,$v->receipt_no.' · '.$v->reason,$v->refund_reference);}
  foreach(DB::table('expenses')->where('school_id',$sid)->whereIn('campus_id',$campuses)->where('status','paid')->where('paid_on','<=',$to)->orderBy('id')->get() as $p){if(!$p->snapshot||!$p->paid_on)$this->fin->fail('An older paid expense needs reviewed payment metadata.');$add('expense_payment',$p->id,$p->campus_id,$p->bank_account_id,$p->method,$p->paid_on,-SchoolFees::cents($p->amount),false,'Expense #'.$p->id.' · '.$p->payee,$p->reference);}
  if(DB::table('expenses')->where('school_id',$sid)->whereIn('campus_id',$campuses)->where('status','paid')->whereNull('paid_on')->exists())$this->fin->fail('A legacy paid expense has no payment date; review it before reporting.');
  foreach(DB::table('expense_reversals as v')->join('expenses as e','e.id','=','v.expense_id')->where('v.school_id',$sid)->whereIn('e.campus_id',$campuses)->where('v.status','approved')->where('v.effective_on','<=',$to)->orderBy('v.id')->get(['v.*','e.campus_id']) as $v)$add('expense_'.$v->kind,$v->id,$v->campus_id,$v->bank_account_id,$v->method,$v->effective_on,SchoolFees::cents($v->amount),$v->kind==='correction','Expense #'.$v->expense_id.' · '.$v->reason,$v->reference);
  foreach(DB::table('salary_payments')->where('school_id',$sid)->whereIn('campus_id',$campuses)->where('paid_at','<=',$before)->orderBy('id')->get() as $p){if($p->method!=='cash'&&!$p->bank_account_id)$this->fin->fail('A legacy salary payment has no non-cash account.');$add('salary_payment',$p->id,$p->campus_id,$p->bank_account_id,$p->method,$this->day($p->paid_at),-SchoolFees::cents($p->amount),false,'Salary payment #'.$p->id,$p->reference);}
  foreach(DB::table('salary_payment_reversals as v')->join('salary_payments as p','p.id','=','v.salary_payment_id')->where('v.school_id',$sid)->whereIn('p.campus_id',$campuses)->where('v.reversed_at','<=',$before)->orderBy('v.id')->get(['v.*','p.campus_id','p.bank_account_id','p.method']) as $v)$add('salary_correction',$v->id,$v->campus_id,$v->bank_account_id,$v->method,$this->day($v->reversed_at),SchoolFees::cents($v->amount),true,'Salary #'.$v->salary_payment_id.' · '.$v->reason);
  foreach(DB::table('staff_advances')->where('school_id',$sid)->whereIn('campus_id',$campuses)->whereNotNull('paid_on')->where('paid_on','<=',$to)->orderBy('id')->get() as $p){if(!in_array($p->status,['paid','void'],true)||!$p->method||$p->method!=='cash'&&!$p->bank_account_id)$this->fin->fail('A legacy disbursed staff advance needs reviewed payment metadata.');$add('advance_payment',$p->id,$p->campus_id,$p->bank_account_id,$p->method,$p->paid_on,-SchoolFees::cents($p->amount),false,'Staff advance #'.$p->id,$p->reference);if($p->status==='void'){if(!$p->voided_at)$this->fin->fail('A voided paid advance has no correction date; review its history first.');$add('advance_correction',$p->id,$p->campus_id,$p->bank_account_id,$p->method,$this->day($p->voided_at),SchoolFees::cents($p->amount),true,'Void staff advance #'.$p->id);}}
  if(DB::table('staff_advances as a')->join('staff_profiles as p','p.id','=','a.staff_profile_id')->join('membership_campuses as m','m.membership_id','=','p.membership_id')->where('a.school_id',$sid)->whereIn('m.campus_id',$campuses)->whereNotNull('a.paid_on')->whereNull('a.campus_id')->exists())$this->fin->fail('A legacy disbursed advance has no campus; reconcile it first.');
  usort($rows,fn($a,$b)=>[$a['date'],$a['key']]<=>[$b['date'],$b['key']]);return $rows;
 }
 public function totals(array $rows):array{$incoming=$outgoing=$corrections=0;$accounts=[];foreach($rows as $r){$n=$this->fin->cents($r['delta'],true);if($r['correction'])$corrections+=$n;elseif($n>=0)$incoming+=$n;else $outgoing-=$n;$k=$r['account_key'];$accounts[$k]=($accounts[$k]??0)+$n;}ksort($accounts);return ['inflow'=>$this->fin->money($incoming),'outflow'=>$this->fin->money($outgoing),'corrections'=>$this->fin->money($corrections),'actual_net'=>$this->fin->money($incoming-$outgoing),'book_net'=>$this->fin->money($incoming-$outgoing+$corrections),'accounts'=>array_map(fn($v)=>$this->fin->money($v),$accounts)];}
 public function report(Request $r,array $d):array{[$sid,$scope]=$this->fin->context($r);if(!empty($d['campus_id'])){$this->fin->campus($r,$d['campus_id']);$scope=[$d['campus_id']];}if(CarbonImmutable::parse($d['from'])->diffInDays($d['to'])>366)$this->fin->fail('Choose a report range of at most 367 days.');$rows=$this->rows($r,$scope,$d['from'],$d['to']);if(isset($d['account_key'])&&$d['account_key']!=='all')$rows=array_values(array_filter($rows,fn($v)=>$v['account_key']===$d['account_key']));return ['from'=>$d['from'],'to'=>$d['to'],'rows'=>$rows,'totals'=>$this->totals($rows),'note'=>'Recorded payment movements, not profit or a complete bank statement. Book corrections are shown separately from actual inflow/outflow. Unpaid expenses, payroll approval and advance recovery create no new cash movement.'];}
}
